window.__T__=[{"i":7480,"text":"一张高质量的日式食品广告横幅。背景为温暖且带有柔和虚化效果的木桌，点缀着金色的稻穗。画面中右侧，{argument name=\"main dish\" default=\"一碗热气腾腾的白米饭，上面放着一颗生蛋黄，并淋上酱油\"} 盛放在竖条纹陶瓷碗中。右侧有一个白色小碟，里面整齐摆放着 3 片酱菜（一片绿色黄瓜、一片橙色胡萝卜、一片白色萝卜），旁边是一个虚化的木制味噌汤碗。左上角，醒目优雅的日文标题写着 {argument name=\"headline text\" default=\"甘み、つや、粘り。三拍子そろったおいしさ。\"}，下方配有较小的副标题 {argument name=\"subheadline text\" default=\"日本の食卓に、最高の一杯を。\"}。左下角展示了一袋 5kg 装的塑料包装大米，标签上写着 {argument name=\"product name\" default=\"新潟県産 こしひかり\"}。右上角是一个圆形的金色箔奖章，显示文字 {argument name=\"badge text\" default=\"米の食味ランキング 特A 獲得\"}。右下角边缘处印有细小的说明文字。整体光线温暖、诱人且专业，突显了米饭和鸡蛋的晶莹质感。","imgs":["https://r2.qqsrc.com/images/originals/14179.jpg"]},{"i":7481,"text":"{\n  \"type\": \"网站落地页模型\",\n  \"theme\": \"深色模式，现代，科幻室内风格\",\n  \"color_palette\": [\n    \"深青色\",\n    \"{argument name=\\\"primary color\\\" default=\\\"青色\\\"}\",\n    \"冷白色\",\n    \"炭灰色\"\n  ],\n  \"header\": {\n    \"logo\": \"带有圆点的月牙图标\",\n    \"brand_name\": \"{argument name=\\\"brand name\\\" default=\\\"GraviLune\\\"}\",\n    \"navigation_links\": {\n      \"count\": 5,\n      \"labels\": [\n        \"产品特性\",\n        \"使用方法\",\n        \"核心技术\",\n        \"设计理念\",\n        \"常见问题\"\n      ]\n    },\n    \"cta_button\": \"立即购买\"\n  },\n  \"hero_content\": {\n    \"position\": \"左侧\",\n    \"headline\": \"{argument name=\\\"headline text\\\" default=\\\"随心所欲，设计房间的重力。\\\"}\",\n    \"subtext\": \"清晨专注时轻盈，深夜入眠时深沉。通过调节重力密度，打造改变空间体验的室内照明艺术。\",\n    \"buttons\": {\n      \"count\": 2,\n      \"primary\": \"调节重力 (发光青色，圆角)\",\n      \"secondary\": \"查看空间变化 (轮廓线，播放图标)\"\n    },\n    \"feature_badges\": {\n      \"count\": 3,\n      \"labels\": [\n        \"三档重力模式\",\n        \"家具悬浮感\",\n        \"安全设计\"\n      ]\n    }\n  },\n  \"visual_scene\": {\n    \"position\": \"右侧及背景\",\n    \"setting\": \"{argument name=\\\"background setting\\\" default=\\\"夜晚的现代客厅，窗外满月\\\"}\",\n    \"main_product\": \"{argument name=\\\"product description\\\" default=\\\"大型时尚圆形吊灯，散发冷白光芒\\\"}\",\n    \"floating_objects\": {\n      \"count\": 7,\n      \"items\": [\n        \"2 本打开的书\",\n        \"1 本合上的书\",\n        \"1 个黑色咖啡杯\",\n        \"1 部智能手机\",\n        \"2 支笔\"\n      ]\n    },\n    \"table_objects\": \"3 本书堆叠在木质咖啡桌上方轻微悬浮\",\n    \"furniture\": \"左侧深色沙发，木质咖啡桌\"\n  },\n  \"footer_element\": \"底部居中的 SCROLL 文字及向下箭头指示\"\n}","imgs":["https://r2.qqsrc.com/images/originals/14180.jpg"]},{"i":7482,"text":"{\n  \"type\": \"2x2 横幅广告网格\",\n  \"theme\": \"{argument name=\\\"school type\\\" default=\\\"社交媒体学校\\\"}\",\n  \"demographic\": \"{argument name=\\\"model demographic\\\" default=\\\"年轻日本女性\\\"}\",\n  \"color_palette\": \"{argument name=\\\"primary color theme\\\" default=\\\"粉色和浅蓝色\\\"}\",\n  \"layout\": {\n    \"panels\": [\n      {\n        \"position\": \"左上\",\n        \"color\": \"粉色\",\n        \"subject\": \"扎发女性，手托下巴，使用笔记本电脑\",\n        \"headline\": \"{argument name=\\\"top left headline\\\" default=\\\"零基础也能 轻松上手♡\\\"}\",\n        \"subheadline\": \"在社交媒体学校 实现理想工作方式\",\n        \"icon_count\": 3,\n        \"icon_labels\": [\"新手友好\", \"从基础学起\", \"居家学习\"],\n        \"cta_button\": \"免费说明会 >\"\n      },\n      {\n        \"position\": \"右上\",\n        \"color\": \"浅蓝色\",\n        \"subject\": \"长发女性，手持智能手机\",\n        \"headline\": \"{argument name=\\\"top right headline\\\" default=\\\"用社交媒体 改变未来\\\"}\",\n        \"subheadline\": \"从内容发布、运营到变现 全面掌握！\",\n        \"icon_count\": 3,\n        \"icon_labels\": [\"内容力\", \"运营力\", \"变现力\"],\n        \"cta_button\": \"立即查看 >\"\n      },\n      {\n        \"position\": \"左下\",\n        \"color\": \"粉色\",\n        \"subject\": \"扎发女性，低头看笔记本电脑\",\n        \"headline\": \"将爱好 变为职业\",\n        \"subheadline\": \"利用碎片时间 轻松学习♪\",\n        \"icon_count\": 3,\n        \"icon_labels\": [\"碎片时间学习\", \"自主节奏\", \"发挥所长\"],\n        \"cta_button\": \"查看详情 >\"\n      },\n      {\n        \"position\": \"右下\",\n        \"color\": \"浅蓝色\",\n        \"subject\": \"长发女性，身着白衬衫，双手放在桌上\",\n        \"headline\": \"实现属于你的 理想工作方式♡\",\n        \"subheadline\": \"提供一对一辅导\",\n        \"icon_count\": 3,\n        \"icon_labels\": [\"一对一安心指导\", \"定制学习计划\", \"全程陪伴支持\"],\n        \"cta_button\": \"免费咨询 >\"\n      }\n    ]\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/14181.jpg"]},{"i":7483,"text":"{\n  \"type\": \"网站落地页模型\",\n  \"theme\": \"未来感记忆转食品 3D 打印机\",\n  \"header\": {\n    \"logo\": \"{argument name=\\\"brand name\\\" default=\\\"KIOKU BITE\\\"}，带有云朵和咬痕图标\",\n    \"navigation_links\": {\n      \"count\": 6,\n      \"labels\": [\"产品特色\", \"工作原理\", \"菜单\", \"画廊\", \"礼品\", \"常见问题\"]\n    },\n    \"icons\": [\"用户个人资料\", \"带有零标记的购物车\"]\n  },\n  \"layout\": {\n    \"left_column\": {\n      \"headline\": \"{argument name=\\\"headline text\\\" default=\\\"让记忆，触手可及。\\\"}\",\n      \"headline_style\": \"大号、多彩、圆润字体\",\n      \"subheadline\": \"{argument name=\\\"product description\\\" default=\\\"一款通过读取照片、音频和位置信息中的情感轮廓，以味道、口感和温度重现记忆的记忆甜点打印机。\\\"}\",\n      \"call_to_action_buttons\": {\n        \"count\": 2,\n        \"primary\": \"渐变背景，文字为 '{argument name=\\\"primary button text\\\" default=\\\"打印记忆\\\"} >'\",\n        \"secondary\": \"白色背景，黑色边框，文字为 '查看菜单 >'\"\n      },\n      \"feature_badges\": {\n        \"count\": 3,\n        \"style\": \"药丸形状，带有图标\",\n        \"labels\": [\"情感味觉转换 (大脑图标)\", \"3 分钟打印 (时钟图标)\", \"适合送礼 (礼品图标)\"]\n      }\n    },\n    \"right_column\": {\n      \"main_product\": \"时尚、白色、未来感 3D 食品打印机设备\",\n      \"printer_screen\": \"数字显示屏，显示 '打印中...'，一个 100% 的进度圆环，以及一个 {argument name=\\\"printing scene\\\" default=\\\"两人在日落海滩\\\"} 的缩略图\",\n      \"printer_interior\": \"正在打印发光的半透明立方体甜点，内部包含一个 {argument name=\\\"printing scene\\\" default=\\\"两人在日落海滩\\\"} 的微型 3D 立体模型\",\n      \"floating_elements\": {\n        \"count\": 4,\n        \"description\": \"半透明的记忆气泡，包含声波、日落照片、微笑的孩子和地图定位点，周围环绕着漂浮的粉色花瓣\"\n      }\n    },\n    \"foreground\": {\n      \"plated_desserts\": {\n        \"count\": 4,\n        \"descriptions\": [\n          \"雪球圆顶，内含桥上行人的樱花场景\",\n          \"云朵状白色甜点，中心带有粉色心形\",\n          \"圆柱形蛋糕，形似翻滚的蓝色海浪\",\n          \"多面宝石状紫色星系甜点\"\n        ]\n      }\n    }\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/14182.jpg"]},{"i":7484,"text":"{\"type\": \"瓶装绿茶饮料宣传海报\", \"product\": {\"type\": \"装有黄绿色茶水的透明 PET 塑料瓶\", \"label\": \"带有绿色字体的白色标签，包含产品名称 '{argument name=\\\"product name\\\" default=\\\"清風茶\\\"}'、副标题 '緑茶 Seifucha'，以及竖排文字 '国産茶葉使用' 和 '香り豊か、後味さわやか'\"}, \"background\": \"明亮、清新、阳光充足的户外氛围，动态水花环绕瓶身，并点缀着鲜活的绿茶叶\", \"layout\": {\"sections\": [{\"title\": \"headline\", \"position\": \"top-left\", \"text\": \"{argument name=\\\"main headline\\\" default=\\\"新発売\\\"}\", \"style\": \"带有金色下划线和绿色小叶子装饰的大号红色文字\"}, {\"title\": \"catchphrase\", \"position\": \"mid-left\", \"text\": \"{argument name=\\\"catchphrase\\\" default=\\\"毎日に、すっきり。\\\"}\", \"style\": \"深绿色文字\"}, {\"title\": \"features\", \"position\": \"lower-left\", \"count\": 2, \"labels\": [\"国産茶葉使用\", \"香り豊か、後味さわやか\"], \"style\": \"带有绿叶图标的白色胶囊状横幅\"}, {\"title\": \"price_badge\", \"position\": \"top-right\", \"text\": \"今だけ!! 特別価格 {argument name=\\\"price\\\" default=\\\"128円\\\"} (税込)\", \"style\": \"带有白黄色文字的红色圆形贴纸\"}, {\"title\": \"promo_banner\", \"position\": \"bottom-left\", \"text\": \"期間限定のお得価格!\", \"style\": \"带有黄白色文字的倾斜红色丝带\"}, {\"title\": \"footer\", \"position\": \"bottom-edge\", \"text\": \"{argument name=\\\"footer text\\\" default=\\\"全国のコンビニ・スーパーで発売中\\\"}\", \"style\": \"带有白色购物车图标的纯绿色水平横条\"}]}}","imgs":["https://r2.qqsrc.com/images/originals/14183.jpg"]},{"i":7485,"text":"{\n  \"type\": \"网站落地页模型\",\n  \"theme\": \"魔幻现实主义，舒适夜晚，奇幻\",\n  \"color_palette\": [\"深海军蓝\", \"暖金色\", \"发光琥珀色\"],\n  \"header\": {\n    \"logo\": \"{argument name=\\\"brand name\\\" default=\\\"BiblioSleep\\\"}，带有新月和打开的书本图标\",\n    \"navigation_links\": {\n      \"count\": 6,\n      \"labels\": [\"设计理念\", \"体验机制\", \"被褥工艺\", \"体验列表\", \"用户评价\", \"常见问题\"]\n    },\n    \"utilities\": {\n      \"count\": 2,\n      \"icons\": [\"用户资料\", \"购物袋\"]\n    },\n    \"cta_button\": \"立即预订\"\n  },\n  \"hero_section\": {\n    \"left_panel\": {\n      \"headline\": \"{argument name=\\\"main headline\\\" default=\\\"在阅读之前，先潜入那个世界安眠。\\\"}\",\n      \"subheadline\": \"{argument name=\\\"subheadline\\\" default=\\\"这是一款阅读前使用的晚安被，让您在翻开书页前，就能预先体验书中世界的氛围、温度、情感与风景。\\\"}\",\n      \"buttons\": {\n        \"count\": 2,\n        \"styles\": [\"实心金色带书本图标\", \"轮廓线带打开的书本图标\"],\n        \"labels\": [\"进入故事 >\", \"体验列表 >\"]\n      },\n      \"feature_icons\": {\n        \"count\": 3,\n        \"layout\": \"左下角水平排列\",\n        \"items\": [\n          {\"icon\": \"带有山脉和星星的书本\", \"label\": \"未读书籍的世界观体验\"},\n          {\"icon\": \"海浪上的新月\", \"label\": \"安眠调节\"},\n          {\"icon\": \"带有闪光点的打开书本\", \"label\": \"提升阅读欲望\"}\n        ]\n      }\n    },\n    \"right_panel_and_background\": {\n      \"subject\": \"年轻女子在床上安详入睡\",\n      \"environment\": \"光线昏暗的舒适卧室，窗外可见远处的城市灯光，床头有一盏暖色台灯\",\n      \"focal_point\": \"一条深蓝色被子，上面覆盖着发光的金色星座线条\",\n      \"magical_elements\": {\n        \"description\": \"{argument name=\\\"magical element\\\" default=\\\"从被褥褶皱中浮现出的微型奇幻场景\\\"}\",\n        \"scene_count\": 5,\n        \"scene_details\": [\"穿越石拱桥的蒸汽火车\", \"哥特式城堡\", \"风格化海浪上的帆船\", \"松林中的舒适小屋\", \"圆顶宫殿\"],\n        \"effects\": \"周围环绕着体积感发光云雾、温暖的微型灯光和漂浮的闪光点\"\n      },\n      \"corner_badge\": {\n        \"position\": \"右下角\",\n        \"style\": \"金色月桂花环\",\n        \"text\": \"扩展阅读体验的晚安被 BiblioSleep\"\n      }\n    }\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/14185.jpg"]},{"i":7486,"text":"{\"type\": \"2x2 网格宣传横幅广告\", \"theme\": \"{argument name=\\\"course theme\\\" default=\\\"社交媒体内容创作学校\\\"}\", \"panels\": [{\"position\": \"左上\", \"color_palette\": \"浅蓝与粉色柔和渐变\", \"subject\": \"年轻女性微笑着，手托下巴，前景有智能手机和环形补光灯\", \"typography\": {\"headline\": \"{argument name=\\\"top left headline\\\" default=\\\"将发布内容转化为工作，SNS 学院\\\"}\", \"subheadings\": [\"热爱，成就我的未来！\", \"欢迎有志成为创作者的你！\"]}, \"layout_elements\": {\"bullet_points_count\": 3, \"call_to_action_button\": \"粉色按钮，标注为 '免费体验 >'\"}}, {\"position\": \"右上\", \"color_palette\": \"深蓝与青色几何风格\", \"subject\": \"年轻男性专注地看着三脚架上的专业相机，配有环形补光灯\", \"typography\": {\"headline\": \"{argument name=\\\"top right headline\\\" default=\\\"学习如何制作吸睛贴文\\\"}\", \"subheadings\": [\"策划、拍摄、运营支持\"]}, \"layout_elements\": {\"circular_icons_count\": 3, \"icon_types\": [\"灯泡\", \"相机\", \"柱状图\"], \"call_to_action_button\": \"黄色按钮，标注为 '查看详情 >'\"}}, {\"position\": \"左下\", \"color_palette\": \"柔和米色与白色美学\", \"subject\": \"年轻女性若有所思地看向侧面，背景为情绪板\", \"typography\": {\"headline\": \"{argument name=\\\"bottom left headline\\\" default=\\\"培养属于你的世界观\\\"}\", \"subheadings\": [\"你的个性，就是最大的优势。\", \"SNS 品牌塑造课程\"]}, \"layout_elements\": {\"horizontal_icons_count\": 3, \"icon_types\": [\"调色板\", \"人物\", \"爱心\"], \"call_to_action_button\": \"粉色按钮，标注为 '立即查看 >'\"}}, {\"position\": \"右下\", \"color_palette\": \"活力粉与洋红色波普设计\", \"subject\": \"年轻女性灿烂微笑，指向文字，扎着丸子头，三脚架上架着智能手机\", \"typography\": {\"headline\": \"{argument name=\\\"bottom right headline\\\" default=\\\"通过热爱的内容建立粉丝群\\\"}\", \"subheadings\": [\"实践型课程\"]}, \"layout_elements\": {\"bullet_points_count\": 4, \"call_to_action_button\": \"黄色按钮，标注为 '立即报名 >'\"}}]}","imgs":["https://r2.qqsrc.com/images/originals/14186.jpg"]},{"i":7487,"text":"{\n  \"type\": \"电影海报网格\",\n  \"layout\": \"2x2 网格\",\n  \"posters\": [\n    {\n      \"position\": \"左上\",\n      \"genre\": \"科幻喜剧\",\n      \"visuals\": \"一名日本上班族坐在拥挤的电车里神情紧张，身旁坐着两名穿着商务装的外星人：一只正在看智能手机的青蛙状外星人，和一只正在看报纸的蓝色章鱼状外星人。\",\n      \"text_elements\": {\n        \"tagline_top\": \"隣の席のアイツ、実は宇宙人でした。\",\n        \"train_display\": \"次は 地球 (ちきゅう) Next Earth\",\n        \"tagline_side\": \"这个星球的常识，在不知不觉中被更新了。\",\n        \"main_title\": \"{argument name=\\\"poster 1 title\\\" default=\\\"となりの宇宙人\\\"}\",\n        \"cast\": \"星野贞夫、章鱼烧·Z、青蛙达·X\",\n        \"release_date\": \"6 月 13 日 (周五) 全国公映\"\n      }\n    },\n    {\n      \"position\": \"右上\",\n      \"genre\": \"超现实浪漫\",\n      \"visuals\": \"一名穿着深色夹克的男子深情地拥抱着一个巨大的明太子海苔饭团。他们坐在美丽的夕阳下的岩石海滩上。\",\n      \"text_elements\": {\n        \"tagline\": \"めんたいこは、裏切らない。\",\n        \"main_title\": \"{argument name=\\\"poster 2 title\\\" default=\\\"めんたいこ ひとすじ\\\"}\",\n        \"cast\": \"中尾真一、明太子、博多满、高菜由香里、海苔平\",\n        \"release_date\": \"7 月 18 日 (周五) 沁人心脾的咸味系爱情故事\"\n      }\n    },\n    {\n      \"position\": \"左下\",\n      \"genre\": \"抢劫喜剧\",\n      \"visuals\": \"一位穿着豹纹衬衫、满脸喜悦的老妇人疯狂大笑，手里拿着一把日元钞票。钱像雨一样在她周围落下。前景中有一只快乐的浣熊。\",\n      \"text_elements\": {\n        \"tagline\": \"人生、まだまだ使いきってなんかない！\",\n        \"main_title\": \"{argument name=\\\"poster 3 title\\\" default=\\\"老後の逆襲\\\"}\",\n        \"subtitle\": \"〜捣蛋狸猫与亿万富翁〜\",\n        \"cast\": \"巴巴芭·芭芭拉、狸吉、有钱婆婆、遗产真由美、税务师冈萨雷斯\",\n        \"release_date\": \"9 月 5 日 (周五) 痛快！下克上娱乐大片！\"\n      }\n    },\n    {\n      \"position\": \"右下\",\n      \"genre\": \"灾难惊悚\",\n      \"visuals\": \"戏剧性的灾难场景，洗衣篮、衬衫和衣物被吸入东京废墟上空（背景可见东京塔）的暴风雨末日天空中。\",\n      \"text_elements\": {\n        \"tagline\": \"それは、静かに、確実に、洗濯物を奪っていく。\",\n        \"main_title\": \"{argument name=\\\"poster 4 title\\\" default=\\\"洗濯物 ストーム\\\"}\",\n        \"cast\": \"森拓也、干场香织、风间春树、衣架·隆、晾衣夹·健\",\n        \"release_date\": \"8 月 29 日 (周五) 全国的天空，危在旦夕。\"\n      }\n    }\n  ]\n}","imgs":["https://r2.qqsrc.com/images/originals/14187.jpg"]},{"i":7488,"text":"一张电影感十足的日式电影海报，呈现了一个浪漫而忧郁的场景：夜晚，雨中的火车站站台上，一男一女面对面站立。左侧高大的男子身穿深色外套，背着背包，撑着一把黑伞遮住两人。右侧的女子身穿卡其色风衣，抬头注视着他。右侧轨道上停着一列红白相间的通勤列车，车头印有日文和英文的“Tokyo”字样。左侧的车站站牌标示着日文的“山手线”。灯光氛围忧郁，城市霓虹灯倒映在湿漉漉的站台上。海报包含醒目的文字叠加。顶部横向标语为 {argument name=\"top tagline\" default=\"あの日、言えなかった言葉がある。\"}。左侧纵向标语为 {argument name=\"side tagline\" default=\"あの日、置き去りにした想い 今、ふたりをつなぐ...\"}。下方中央是巨大的主标题 {argument name=\"main title\" default=\"最後の切符\"}，采用白色衬线字体，下方配有红色的草书副标题 {argument name=\"romaji subtitle\" default=\"Saigo no Kippu\"}。标题下方是两行日文演员表，随后是一段密集的日文制作人员名单。底部中央是红色网站 URL 和上映信息 {argument name=\"release info\" default=\"2025年秋 全国ロードショー\"}。底部两侧配有两个带有日文的金色获奖桂冠。","imgs":["https://r2.qqsrc.com/images/originals/14188.jpg"]},{"i":7489,"text":"{\n  \"type\": \"动漫风格动画电影海报\",\n  \"scene\": \"夜晚，黑暗魔法森林中一座发光的魔法多层树屋餐厅，被串灯和温暖的窗光照亮。\",\n  \"subjects\": {\n    \"children\": \"前景中心有 2 名面向餐厅的孩子：一个背着背包、提着灯笼的男孩，以及一个穿着红外套、戴着贝雷帽、提着灯笼的女孩。\",\n    \"animals\": \"4 只拟人化动物：左下角拿着菜单书的厨师熊，左上方树枝上拉小提琴的猫头鹰和吹笛子的松鼠，右侧中间拉大提琴的獾，以及右下角穿着西装拿着标牌的兔子。\",\n    \"creatures\": \"3 只眼睛发光的小型黑色煤灰精灵状生物（右下角）。\",\n    \"floating_food\": \"4 种漂浮在空中的发光食物：汤、煎饼、蛋包饭和水果芭菲。\"\n  },\n  \"layout\": {\n    \"top_text\": \"{argument name=\\\"top catchphrase\\\" default=\\\"美味的奇迹，今晚开启。\\\"}\",\n    \"building_sign\": \"{argument name=\\\"restaurant name\\\" default=\\\"森林餐厅\\\"}\",\n    \"left_board\": \"今日推荐\\n・森林浓汤\\n・星空蛋包饭\\n・松软煎饼\\n・幸福芭菲\\n...以及更多！\",\n    \"right_board\": \"欢迎光临！\\n这里是\\n每个人都能展露笑容的地方。\",\n    \"main_title\": {\n      \"text\": \"{argument name=\\\"movie title\\\" default=\\\"奇妙森林餐厅\\\"}\",\n      \"styling\": \"带有厨师帽、叉子和勺子图案的大型艺术字体。\"\n    },\n    \"rabbit_sign\": \"吃饱啦！欢迎再来！\",\n    \"bottom_left_badge\": \"{argument name=\\\"genre badge\\\" default=\\\"全家共享！暖心冒险奇幻电影\\\"}\",\n    \"bottom_center_credits\": \"虚构的演职人员名单（日文）。\",\n    \"bottom_release_date\": \"{argument name=\\\"release date\\\" default=\\\"2025 年暑期上映！\\\"}\",\n    \"bottom_right\": \"带有“获取最新资讯！”文字的二维码\"\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/14191.jpg"]},{"i":7490,"text":"{\n  \"type\": \"2x2 网格横幅广告\",\n  \"theme\": \"针对 {argument name=\\\"target audience\\\" default=\\\"宝妈\\\"} 的 {argument name=\\\"main theme\\\" default=\\\"社交媒体学校\\\"}\",\n  \"design_style\": \"柔和、亲切、明亮的灯光，采用 {argument name=\\\"color palette\\\" default=\\\"柔和的绿色、白色和自然米色调\\\"}\",\n  \"layout\": {\n    \"sections\": [\n      {\n        \"position\": \"左上\",\n        \"visual_style\": \"摄影\",\n        \"image_description\": \"一位微笑着的女性在桌前使用笔记本电脑，背景模糊处有一个幼儿正在玩玩具。\",\n        \"headlines\": [\"支持宝妈的“想尝试”！\", \"育儿同时也能学习\", \"社交媒体学校\"],\n        \"features\": {\n          \"count\": 1,\n          \"type\": \"图标加文字\",\n          \"labels\": [\"在家轻松提升技能 (附房屋图标)\"]\n        },\n        \"call_to_action_button\": \"免费咨询\"\n      },\n      {\n        \"position\": \"右上\",\n        \"visual_style\": \"摄影\",\n        \"image_description\": \"一位微笑着的女性拿着白色马克杯，注视着笔记本电脑。\",\n        \"headlines\": [\"一点点时间，就是一大步。\", \"将碎片时间连接未来\", \"视频课程，易于学习\"],\n        \"features\": {\n          \"count\": 3,\n          \"type\": \"圆形图标下方配文字\",\n          \"labels\": [\"手机也能学 (手机图标)\", \"每天 15 分钟即可 (时钟图标)\", \"可反复观看 (播放按钮图标)\"]\n        },\n        \"call_to_action_button\": \"查看详情\"\n      },\n      {\n        \"position\": \"左下\",\n        \"visual_style\": \"水彩插画\",\n        \"image_description\": \"一位扎着发髻的女性微笑着面对笔记本电脑，旁边放着一个绿色马克杯的插画。\",\n        \"headlines\": [\"初学者也没问题！ (附初学者标志)\", \"在家即可从事的社交媒体工作\", \"无需经验\"],\n        \"features\": {\n          \"count\": 3,\n          \"type\": \"圆形图标下方配文字\",\n          \"labels\": [\"完善的支持体系 (爱心图标)\", \"不擅长电脑也能安心 (笔记本电脑图标)\", \"建立收入来源 (日元硬币图标)\"]\n        },\n        \"call_to_action_button\": \"立即体验\"\n      },\n      {\n        \"position\": \"右下\",\n        \"visual_style\": \"摄影\",\n        \"image_description\": \"一位微笑着的母亲和年幼的女儿坐在沙发上一起看绘本。\",\n        \"headlines\": [\"珍惜与家人的时光\", \"实现属于自己的工作方式\", \"妈妈的笑容是最好的未来。\"],\n        \"features\": {\n          \"count\": 3,\n          \"type\": \"勾选符号列表\",\n          \"labels\": [\"不受地点和时间限制\", \"兼顾成就感与收入\", \"在身边守护孩子的成长\"]\n        },\n        \"extra_graphics\": \"左下角有房屋和树木的小插画。\",\n        \"call_to_action_button\": \"参加说明会\"\n      }\n    ],\n    \"common_elements\": \"所有面板底部均采用 {argument name=\\\"button style\\\" default=\\\"带有白色文字和向右箭头图标的圆角绿色胶囊按钮\\\"}。\"\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/14192.jpg"]},{"i":7491,"text":"{\n  \"type\": \"1 页动漫漫画\",\n  \"character\": {\n    \"name\": \"{argument name=\\\"character name\\\" default=\\\"柴咲リリー\\\"}\",\n    \"appearance\": \"长 {argument name=\\\"hair color\\\" default=\\\"深紫色\\\"} 头发，佩戴白色丝带，{argument name=\\\"eye color\\\" default=\\\"紫色\\\"} 双眸，优雅的白色荷叶边衬衫搭配深色丝带领结，精致的耳环\"\n  },\n  \"style\": \"高细节动漫插画，柔和光影，优雅风格，花卉元素，{argument name=\\\"color palette\\\" default=\\\"紫白配色\\\"} 美学\",\n  \"layout\": {\n    \"structure\": \"包含 1 个标题栏、6 个编号分镜和 1 个页脚的漫画页面\",\n    \"title_block\": {\n      \"position\": \"左上角\",\n      \"content\": \"带有 'L' 的华丽纹章，文字 '{argument name=\\\"character name\\\" default=\\\"柴咲リリー\\\"}'，'Shibasaki Lily'，'{argument name=\\\"comic title\\\" default=\\\"日常エッセイ 第1話 紅茶が少し冷めるまで\\\"}'\"\n    },\n    \"panels\": [\n      {\n        \"number\": 1,\n        \"position\": \"右上角\",\n        \"scene\": \"角色托腮，注视着优雅的茶具，窗外透进晨光\",\n        \"text_box\": \"朝の紅茶は、少しだけ冷めるのを待つのが好きです。\"\n      },\n      {\n        \"number\": 2,\n        \"position\": \"中左\",\n        \"scene\": \"侧面视角，角色手持茶杯，神情若有所思\",\n        \"text_box\": \"熱すぎるままだと、味が急いでしまう気がして。\"\n      },\n      {\n        \"number\": 3,\n        \"position\": \"中右\",\n        \"scene\": \"角色伏在桌上，面前摊开一本书，低头神情温柔\",\n        \"text_box\": \"……本当は、紅茶より先に落ち着きたいのは、わたくしの方かもしれませんけれど。\"\n      },\n      {\n        \"number\": 4,\n        \"position\": \"左下\",\n        \"scene\": \"角色在镜子前整理耳环\",\n        \"speech_bubble\": \"よし。\"\n      },\n      {\n        \"number\": 5,\n        \"position\": \"右下\",\n        \"scene\": \"特写，角色闭眼品茶，神情放松\",\n        \"text_box\": \"ちゃんと美味しい、と思える温度になると、少し安心します。\"\n      },\n      {\n        \"number\": 6,\n        \"position\": \"底部通栏\",\n        \"scene\": \"角色温暖微笑，手持茶杯，直视观众，周围环绕着紫色花朵\",\n        \"speech_bubble\": \"今日は、よい一日にできそうですわ。\",\n        \"text_box\": \"柴咲リリーの日常は、たぶん、こんなふうにゆっくり始まります。\"\n      }\n    ],\n    \"footer\": {\n      \"content\": \"お嬢様系VTuber・柴咲リリーの日常エッセイ\"\n    }\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/14193.jpg"]},{"i":7492,"text":"{\n  \"type\": \"3 格漫画页面\",\n  \"style\": \"动漫，高细节，电影级光效，未来感企业风\",\n  \"layout\": {\n    \"structure\": \"上方 1 个宽幅格，下方 2 个方形格\"\n  },\n  \"panels\": [\n    {\n      \"position\": \"上方\",\n      \"shot\": \"宽幅横向镜头\",\n      \"scene\": \"带有落地窗的未来感企业大厅\",\n      \"lighting\": \"{argument name=\\\"time of day\\\" default=\\\"日出\\\"}\",\n      \"background\": \"城市天际线，包含 {argument name=\\\"landmark\\\" default=\\\"东京塔\\\"}\",\n      \"details\": \"全息显示屏，抛光反光地板，接待台，休息椅\"\n    },\n    {\n      \"position\": \"左下方\",\n      \"shot\": \"侧面特写\",\n      \"character\": \"年轻女性，深色头发，黑色职业套装\",\n      \"accessories\": \"带有蓝色发光灯的未来感黑色耳机\",\n      \"speech_bubble\": {\n        \"style\": \"标准圆角\",\n        \"text\": \"{argument name=\\\"character dialogue\\\" default=\\\"数字はいいわ\\\"}\"\n      }\n    },\n    {\n      \"position\": \"右下方\",\n      \"shot\": \"全身镜头，背影，触碰耳机\",\n      \"character\": \"同一女性，黑色套装，黑色高跟鞋，手提黑色托特包\",\n      \"environment\": \"走向安检门\",\n      \"holographic_sign\": \"{argument name=\\\"floor sign\\\" default=\\\"ECHO 42F\\\"}\",\n      \"speech_bubble\": {\n        \"style\": \"未来感尖角\",\n        \"text\": \"{argument name=\\\"AI dialogue\\\" default=\\\"おはようございます、ユキさん。本日は記念すべき ──\\\"}\"\n      }\n    }\n  ]\n}","imgs":["https://r2.qqsrc.com/images/originals/14194.jpg"]},{"i":7493,"text":"{\n  \"type\": \"2x2 横幅广告网格\",\n  \"theme\": \"{argument name=\\\"school name\\\" default=\\\"SNS 学院\\\"}\",\n  \"target_audience\": \"{argument name=\\\"target audience\\\" default=\\\"学生\\\"}\",\n  \"layout\": {\n    \"grid\": \"2x2\",\n    \"panels\": [\n      {\n        \"position\": \"top-left\",\n        \"style\": \"深色霓虹，蓝色与紫色\",\n        \"subject\": \"年轻女性充满希望地抬头看，手持智能手机，身穿紫色卫衣\",\n        \"main_text\": \"{argument name=\\\"banner 1 headline\\\" default=\\\"致想从事 SNS 相关工作的人\\\"}\",\n        \"sub_text\": \"将“热爱”化为现实。迈出改变未来的第一步，就在现在。\",\n        \"elements\": [\n          \"白色与黄色排版\",\n          \"黄色行动号召按钮：查看详情 >\",\n          \"手绘霓虹装饰（皇冠、星星、爱心）\"\n        ]\n      },\n      {\n        \"position\": \"top-right\",\n        \"style\": \"明亮、流行，青色与白色\",\n        \"subject\": \"年轻女性直视镜头微笑，手持智能手机，身穿青色连帽衫，扎着丸子头\",\n        \"main_text\": \"{argument name=\\\"banner 2 headline\\\" default=\\\"让你的内容发布成为利器\\\"}\",\n        \"sub_text\": \"学习策划、编辑与发布\",\n        \"elements\": [\n          \"文字背景采用撕纸纹理\",\n          \"黄色星形贴纸：免费体验\",\n          \"3 个功能图标及文字：灯泡（策划力）、铅笔（编辑力）、纸飞机（发布力）\"\n        ]\n      },\n      {\n        \"position\": \"bottom-left\",\n        \"style\": \"深色、分析感，霓虹紫与绿色\",\n        \"subject\": \"年轻男性若有所思地看着智能手机，身穿黑色连帽衫\",\n        \"main_text\": \"{argument name=\\\"banner 3 headline\\\" default=\\\"不仅是爆款，更要学会数据分析\\\"}\",\n        \"sub_text\": \"#理解增长背后的逻辑，让成长更进一步。\",\n        \"elements\": [\n          \"3 个悬浮的全息数据面板，包含折线图和统计数据（125.6 万，23.8%，12.6%）\",\n          \"底部 3 个功能图标：柱状图（数据分析）、放大镜（改进建议）、靶心（实现成果）\",\n          \"黄色行动号召按钮：了解更多 >\"\n        ]\n      },\n      {\n        \"position\": \"bottom-right\",\n        \"style\": \"明亮、友好，紫色与白色\",\n        \"subject\": \"4 位年轻人（3 女 1 男）聚在一起对着智能手机微笑\",\n        \"main_text\": \"通过 SNS 拓展未来的可能性\",\n        \"sub_text\": \"与伙伴共同学习的社区\",\n        \"elements\": [\n          \"文字背景采用撕纸纹理\",\n          \"3 个带图标的要点（人物、对话气泡、上升图表）\",\n          \"2 张宝丽来风格的插图，展示学生在书桌前学习的场景\",\n          \"黄色行动号召按钮：立即加入 >\"\n        ]\n      }\n    ]\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/14196.jpg"]},{"i":7494,"text":"{\n  \"type\": \"6 格 Q 版漫画\",\n  \"header\": {\n    \"logo\": \"L 徽章\",\n    \"main_title\": \"{argument name=\\\"main title\\\" default=\\\"柴咲莉莉的日常随笔\\\"}\",\n    \"subtitle\": \"{argument name=\\\"subtitle\\\" default=\\\"第 1 话 在红茶变凉之前\\\"}\",\n    \"top_right_bubble\": \"我是大小姐系 VTuber {argument name=\\\"character name\\\" default=\\\"柴咲莉莉\\\"}♪\"\n  },\n  \"character\": {\n    \"style\": \"Q 版动漫少女\",\n    \"hair\": \"{argument name=\\\"hair color\\\" default=\\\"深紫色\\\"}，长发，发带\",\n    \"eyes\": \"紫色\",\n    \"outfit\": \"{argument name=\\\"outfit\\\" default=\\\"白紫色哥特萝莉裙，配黑色蝴蝶结\\\"}\"\n  },\n  \"layout\": {\n    \"grid\": \"2 列，3 行\",\n    \"panels\": [\n      {\n        \"number\": 1,\n        \"pose\": \"托腮，看着茶杯\",\n        \"dialogue\": \"我喜欢在早晨喝红茶时，稍微等它凉一点。\"\n      },\n      {\n        \"number\": 2,\n        \"pose\": \"专注地盯着茶\",\n        \"sound_effect\": \"盯着……\",\n        \"dialogue\": \"如果太烫的话，总觉得茶的味道会变得急躁。\"\n      },\n      {\n        \"number\": 3,\n        \"pose\": \"沉思，托着头，桌上放着打开的书\",\n        \"dialogue\": \"……其实，比起红茶，或许更需要冷静下来的是我自己吧。\"\n      },\n      {\n        \"number\": 4,\n        \"pose\": \"坚定，握紧拳头\",\n        \"sound_effect\": \"好！\",\n        \"dialogue\": \"只要一件一件地整理好，就没问题。\"\n      },\n      {\n        \"number\": 5,\n        \"pose\": \"闭眼喝茶，神情放松\",\n        \"sound_effect\": \"呼……\",\n        \"dialogue\": \"当温度变得刚好能品出美味时，心里会感到一丝安心。\"\n      },\n      {\n        \"number\": 6,\n        \"pose\": \"微笑，手持茶杯，手指向上，旁边有一只黑白小狗吉祥物\",\n        \"mascot_dialogue\": \"很期待呢～！\",\n        \"dialogue\": \"今天，一定会是美好的一天♪\"\n      }\n    ]\n  },\n  \"footer\": {\n    \"text\": \"柴咲莉莉的日常，大概就是这样慢慢开始的。\",\n    \"decorations\": \"左侧茶杯图标，右侧 L 徽章\"\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/14197.jpg"]},{"i":7495,"text":"{\n  \"type\": \"2x2 广告横幅网格\",\n  \"layout\": \"四个不同的象限，每个象限包含不同风格的商业广告\",\n  \"quadrants\": [\n    {\n      \"position\": \"左上\",\n      \"industry\": \"护肤与美妆\",\n      \"visuals\": \"一位年轻亚洲女性的特写肖像，皮肤清透亮泽，手触脸颊；旁边摆放着一个精致的精华液瓶，配有一个发光的珍珠状球体\",\n      \"brand\": \"LUMIèRE\",\n      \"copy\": [\n        \"{argument name=\\\"beauty catchphrase\\\" default=\\\"わたし史上、いちばんの透明感へ。\\\"}\",\n        \"水润 × 紧致透明感 全效抗衰老精华液\",\n        \"2024 年 4 月 20 日 全新上市\"\n      ],\n      \"color_palette\": \"白色、柔米色、浅灰色\"\n    },\n    {\n      \"position\": \"右上\",\n      \"industry\": \"旅行社\",\n      \"visuals\": \"一名背包客站在岩石悬崖上，俯瞰着湛蓝的峡湾和晴空下雄伟的山脉\",\n      \"brand\": \"TABINOVA\",\n      \"copy\": [\n        \"{argument name=\\\"travel catchphrase\\\" default=\\\"まだ見ぬ景色を探しに行こう。\\\"}\",\n        \"现在就出发去旅行吧\",\n        \"国内外旅游团最高可享 30% 折扣！\",\n        \"截止至 5 月 31 日\"\n      ],\n      \"color_palette\": \"天蓝色、深海蓝、大地绿与棕色\"\n    },\n    {\n      \"position\": \"左下\",\n      \"industry\": \"咖啡与餐饮\",\n      \"visuals\": \"一叠令人垂涎的松软煎饼，上面放着融化的黄油，淋着糖浆，点缀着新鲜草莓和蓝莓；背景中有一杯黑咖啡和一把银色叉子\",\n      \"brand\": \"café miel\",\n      \"copy\": [\n        \"{argument name=\\\"cafe catchphrase\\\" default=\\\"しあわせは、今日のごほうび。\\\"}\",\n        \"用松软即化的煎饼，享受放松的咖啡时光。\",\n        \"季节限定 浆果煎饼 1,480 日元\",\n        \"关注我们！ @cafe_miel_official\"\n      ],\n      \"color_palette\": \"暖米色、诱人的棕色、鲜艳的红色\"\n    },\n    {\n      \"position\": \"右下\",\n      \"industry\": \"B2B SaaS / AI 技术\",\n      \"visuals\": \"等距 3D 插图，展示了微型办公室员工与悬浮的数据仪表盘、条形图及中央 AI 服务器单元进行交互；左下角有 3 个圆形功能图标\",\n      \"brand\": \"{argument name=\\\"tech brand name\\\" default=\\\"SHIFTAI\\\"}\",\n      \"copy\": [\n        \"{argument name=\\\"tech catchphrase\\\" default=\\\"その仕事、AIにおまかせ。\\\"}\",\n        \"将业务效率提升至新阶段。\",\n        \"免费咨询受理中！\",\n        \"点击了解详情\"\n      ],\n      \"color_palette\": \"企业蓝、紫色渐变、清爽白\"\n    }\n  ]\n}","imgs":["https://r2.qqsrc.com/images/originals/14199.jpg"]},{"i":7496,"text":"{\n  \"type\": \"动画电影制作提案文档\",\n  \"overall_layout\": \"分割式布局，上半部分为一张大型电影级海报，下半部分为 5 张详细参考图的网格排列\",\n  \"top_section\": {\n    \"type\": \"电影海报\",\n    \"visual\": \"一名男子、一名女子和一只狗站在废弃的城市街道上，背对观众，望向天空中巨大的、多孔的网状外星结构。右侧立着一块生锈的“RESTRICTED AREA”（禁区）标志牌。\",\n    \"typography\": {\n      \"title\": \"{argument name=\\\"movie title\\\" default=\\\"劇場版 巨骸の向こう側 Fallen Colossus\\\"}\",\n      \"release_date\": \"{argument name=\\\"release date\\\" default=\\\"2027.11.28 ROADSHOW\\\"}\",\n      \"tagline\": \"そこにあるのは、まだ「説明」されていないもの。\",\n      \"credits_studio\": \"{argument name=\\\"studio name\\\" default=\\\"WIT STUDIO\\\"}\"\n    }\n  },\n  \"bottom_sections\": [\n    {\n      \"title\": \"{argument name=\\\"male character name\\\" default=\\\"来栖 武 / Kurusu Takeru\\\"}\",\n      \"type\": \"角色参考图\",\n      \"elements\": {\n        \"full_body_poses\": 3,\n        \"expressions\": 3,\n        \"detail_shots\": 8,\n        \"description\": \"男主角，身穿深色战术夹克和工装裤。包含正面、背面和侧面的全身视图、头像，以及手套、靴子、背包和对讲机的细节标注。\"\n      }\n    },\n    {\n      \"title\": \"{argument name=\\\"female character name\\\" default=\\\"大城 真那 / Oshiro Mana\\\"}\",\n      \"type\": \"角色参考图\",\n      \"elements\": {\n        \"full_body_poses\": 3,\n        \"expressions\": 3,\n        \"detail_shots\": 6,\n        \"description\": \"女主角，身穿灰色战术制服。包含正面、背面和侧面的全身视图、头像，以及夹克、靴子、身份牌和收纳袋的细节标注。\"\n      }\n    },\n    {\n      \"title\": \"カゲ (Kage) 設定画\",\n      \"type\": \"动物角色参考图\",\n      \"elements\": {\n        \"full_body_poses\": 4,\n        \"expressions\": 4,\n        \"detail_shots\": 5,\n        \"description\": \"狗狗伙伴。包含侧面、正面、背面和斜角的全身视图、头像，以及毛发纹理、爪子和摩托车边车的细节标注。\"\n      }\n    },\n    {\n      \"title\": \"第7巨骸 (Remnant-7) 内部区画 設定画\",\n      \"type\": \"环境与载具参考图\",\n      \"elements\": {\n        \"large_diagrams\": 1,\n        \"environment_thumbnails\": 4,\n        \"vehicle_designs\": 1,\n        \"description\": \"多孔外星结构的横截面图、小型环境缩略图，以及包含角色的摩托车设计图。\"\n      }\n    },\n    {\n      \"title\": \"概念艺术\",\n      \"type\": \"场景插画\",\n      \"elements\": {\n        \"characters\": 3,\n        \"vehicles\": 1,\n        \"description\": \"男主角、女主角和带着摩托车边车的狗，停在发光的多孔外星结构前。\"\n      }\n    }\n  ]\n}","imgs":["https://r2.qqsrc.com/images/originals/14202.jpg"]},{"i":7497,"text":"一张电影感动漫风格的科幻电影海报。画面中央，一位有着 {argument name=\"hair color\" default=\"银色长发\"} 和蓝色眼睛的年轻女性自信地坐在一张巨大的、充满未来感的灰色扶手椅上，椅子带有发光的浅蓝色霓虹灯装饰。她身穿黑色风衣，内搭白色高领衬衫，下身穿着黑色长裤和黑色高跟靴。座椅位于一个漂浮在繁星点点的深空中的发光蓝色圆形全息平台上。在她身后，半透明的蓝色全息屏幕显示着数据和行星图像。在顶部中央，系列标题 {argument name=\"series title\" default=\"『電脳椅子探偵シャルロット』\"} 以白色小字呈现，位于优雅衬线字体书写的大型主标题 {argument name=\"main title\" default=\"『天使の涙』\"} 上方。主标题下方是标语 {argument name=\"subtitle\" default=\"すべての記録は、この出会いから始まった。\"}。海报底部中央有一段文字写着 \"This is the first record of Charlotte and W.A.T.S.O.N.\"，随后是醒目的风格化标题 {argument name=\"bottom text\" default=\"シャルロット & W.A.T.S.O.N.\"}，最底部标注着 \"Original Story / Screenplay / Director noriyang\"。整体氛围神秘、充满高科技感且史诗宏大。","imgs":["https://r2.qqsrc.com/images/originals/14203.jpg"]},{"i":7498,"text":"{\n  \"type\": \"{argument name=\\\"grid layout\\\" default=\\\"2x2 日式横幅广告网格\\\"}\",\n  \"panels\": [\n    {\n      \"position\": \"左上\",\n      \"theme\": \"护肤化妆品\",\n      \"subject\": \"一位神情宁静的女性闭眼轻触脸庞的特写肖像\",\n      \"product\": \"带有银色瓶盖的白色精华液瓶\",\n      \"brand\": \"mira\",\n      \"main_copy\": \"{argument name=\\\"skincare catchphrase\\\" default=\\\"わたしの肌に、ごほうびを。\\\"}\",\n      \"sub_copy\": \"滋润充盈，打造通透素肌\",\n      \"badges\": {\n        \"count\": 3,\n        \"labels\": [\n          \"高保湿\",\n          \"暗沉护理\",\n          \"敏感肌适用\"\n        ]\n      },\n      \"footer_box\": \"Mira 保湿精华液 50mL 6,380 日元（含税）\"\n    },\n    {\n      \"position\": \"右上\",\n      \"theme\": \"旅行社\",\n      \"subject\": \"布莱德湖的风景，湖中岛上的教堂、山脉与蓝天\",\n      \"main_copy\": \"{argument name=\\\"travel catchphrase\\\" default=\\\"まだ見ぬ景色に、会いに行こう。\\\"}\",\n      \"sub_copy\": \"触动心灵的旅程，就在你身边。\",\n      \"bottom_banner\": {\n        \"text\": \"留给未来的自己，一段特别的体验。\",\n        \"footer_elements\": {\n          \"count\": 3,\n          \"items\": [\n            \"海内外旅游团众多\",\n            \"限时优惠套餐！\",\n            \"详情请点击 -> (黄色按钮)\"\n          ]\n        }\n      }\n    },\n    {\n      \"position\": \"左下\",\n      \"theme\": \"美食外卖\",\n      \"subject\": \"黑色煎锅上滋滋作响、肉汁四溢的汉堡排，切开后冒着热气，配有胡萝卜和西兰花\",\n      \"main_copy\": \"{argument name=\\\"food catchphrase\\\" default=\\\"じゅわっと、肉のうまみ。\\\"}\",\n      \"sub_copy\": \"严选食材，正宗风味。\",\n      \"badge\": \"使用 100% 国产牛肉 (带牛图标)\",\n      \"bottom_banner\": {\n        \"thumbnail\": \"4 个装汉堡排礼盒\",\n        \"text\": \"美味汉堡排 (4 个装) 冷冻配送\",\n        \"button\": \"点击购买 (带购物车图标的棕色按钮)\"\n      }\n    },\n    {\n      \"position\": \"右下\",\n      \"theme\": \"金融投资应用\",\n      \"subject\": \"智能手机屏幕显示上升趋势的折线图和 1,234,567 日元的余额\",\n      \"brand\": \"treee (带树木图标)\",\n      \"main_copy\": \"{argument name=\\\"app catchphrase\\\" default=\\\"はじめよう、わたしの資産づくり。\\\"}\",\n      \"sub_copy\": \"从小额开始，改变未来。\",\n      \"features\": {\n        \"count\": 3,\n        \"icons\": [\n          \"饼图/时钟\",\n          \"磁铁/硬币\",\n          \"硬币堆\"\n        ],\n        \"labels\": [\n          \"100 日元起投\",\n          \"简洁易用\",\n          \"支持 NISA\"\n        ]\n      },\n      \"badge\": \"免费下载 (绿色圆圈)\",\n      \"footer\": {\n        \"count\": 4,\n        \"elements\": [\n          \"立即下载\",\n          \"App Store 徽标\",\n          \"Google Play 徽标\",\n          \"二维码\"\n        ]\n      }\n    }\n  ]\n}","imgs":["https://r2.qqsrc.com/images/originals/14205.jpg"]},{"i":7499,"text":"一张儿童绘本封面的水彩插画。主角是 {argument name=\"character appearance\" default=\"一位留着绿色短发、长着猫耳、拥有绿色眼睛的可爱兽耳少女\"}。她 {argument name=\"action\" default=\"正开心地笑着，并用毛茸茸的白色手掌竖起中指\"}。她身穿一件带有蓬松白色领子的绿色服装。背景是质感纸张上绘制的柔和绿色叶片和黄色小花。封面顶部有醒目的手绘绿色日文标题“{argument name=\"main title\" default=\"なかゆびさん\"}”。下方是棕色的日文副标题“{argument name=\"subtitle\" default=\"こんにちは\"}”。左侧中部有较小的黑色文字“{argument name=\"author text\" default=\"さく・え：とらの\"}”。图像左侧边缘带有明显的书脊，突显出实体书的质感。","imgs":["https://r2.qqsrc.com/images/originals/14206.png"]},{"i":7500,"text":"{\n  \"type\": \"带有腰封的动漫 CD 珠宝盒封面\",\n  \"character\": {\n    \"name\": \"{argument name=\\\"character name\\\" default=\\\"ななし\\\"}\",\n    \"appearance\": \"慌乱的动漫少女，{argument name=\\\"hair color\\\" default=\\\"粉色配蓝色渐变发梢\\\"}，双马尾，红瞳，汗珠\",\n    \"outfit\": \"黑白女仆装，荷叶边围裙，红色领结，黑色发饰\",\n    \"action\": \"手持托盘，上面有洒出的蓝色冰饮、草莓蛋糕和茶杯；前景中有一个洒出的咖啡杯\"\n  },\n  \"layout\": {\n    \"obi_strip\": {\n      \"position\": \"左侧边缘\",\n      \"color\": \"蓝色\",\n      \"text\": [\"NANASHI 2nd EP\", \"{argument name=\\\"album title\\\" default=\\\"おしごと☆メイド奮闘中！\\\"}\", \"{argument name=\\\"character name\\\" default=\\\"ななし\\\"} (CV. ???)\", \"STEREO\", \"NNXS-002\"]\n    },\n    \"main_title\": {\n      \"position\": \"左上角\",\n      \"text\": [\"NANASHI 2nd EP\", \"{argument name=\\\"album title\\\" default=\\\"おしごと☆メイド奮闘中！\\\"}\", \"- Oshigoto Maid Funtouchu! -\"]\n    },\n    \"quote_bubble\": {\n      \"position\": \"右上角\",\n      \"text\": \"{argument name=\\\"character quote\\\" default=\\\"ドジっちゃっても頑張っちゃう！応援してね…っ♡\\\"}\"\n    },\n    \"to_do_list\": {\n      \"position\": \"中左侧\",\n      \"count\": 5,\n      \"items\": [\"開店準備！\", \"お掃除\", \"メニュー確認\", \"発注チェック\", \"笑顔で接客！\"],\n      \"footer\": \"がんばるぞーっ！ 附带一个小兔子涂鸦\"\n    },\n    \"track_list\": {\n      \"position\": \"左下角\",\n      \"count\": 6,\n      \"tracks\": [\"01. {argument name=\\\"lead track name\\\" default=\\\"メイド開店☆ハプニング！\\\"}\", \"02. がんばれ！ななちゃんタイム！\", \"03. うっかりラプソディー\", \"04. キラキラお給仕中！\", \"05. 夢見るメイドのステップ！\", \"06. {argument name=\\\"lead track name\\\" default=\\\"メイド開店☆ハプニング！\\\"} (Instrumental)\"]\n    },\n    \"sticky_notes\": {\n      \"count\": 2,\n      \"text\": [\"ドリンク補充！\", \"新作スイーツの練習！！☆\"]\n    },\n    \"signature\": {\n      \"position\": \"右下角\",\n      \"text\": \"{argument name=\\\"character name\\\" default=\\\"ななし\\\"}♡ Nanashi\"\n    }\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/14207.jpg"]},{"i":7501,"text":"{\n  \"type\": \"动漫偶像周边商品目录传单\",\n  \"theme_colors\": \"{argument name=\\\"theme color\\\" default=\\\"柔和蓝粉色\\\"}\",\n  \"character\": {\n    \"name\": \"{argument name=\\\"character name\\\" default=\\\"ななし\\\"}\",\n    \"appearance\": \"动漫少女，长款 {argument name=\\\"hair color\\\" default=\\\"粉色\\\"} 头发，蓝色眼睛\",\n    \"attire\": \"{argument name=\\\"outfit\\\" default=\\\"黑白女仆装配红色领结\\\"} 以及蓝色发带\"\n  },\n  \"layout\": {\n    \"header\": {\n      \"left\": \"角色上半身肖像，侧身看向一侧\",\n      \"center\": {\n        \"top_banner\": \"ななし 2nd EP 发行纪念演唱会\",\n        \"main_title\": \"{argument name=\\\"event title\\\" default=\\\"おしごと☆メイド奮闘中！\\\"}\",\n        \"subtitle\": \"~ 工作中☆女仆奋斗中！ ~\",\n        \"section_header\": \"官方周边\"\n      },\n      \"right\": \"包含 3 张小型矩形照片打印件的购买特典信息框\"\n    },\n    \"merchandise_grid\": [\n      { \"id\": \"01\", \"name\": \"亚克力立牌\", \"description\": \"角色全身亚克力立牌\" },\n      { \"id\": \"02\", \"name\": \"徽章\", \"description\": \"6 枚不同表情的圆形徽章套装\" },\n      { \"id\": \"03\", \"name\": \"大浴巾\", \"description\": \"印有角色怀抱心形抱枕图案的大型矩形毛巾\" },\n      { \"id\": \"04\", \"name\": \"T 恤\", \"description\": \"白色 T 恤，正面印有角色图案，背面印有小型 Logo\" },\n      { \"id\": \"05\", \"name\": \"应援毛巾\", \"description\": \"印有角色艺术图和 Logo 的长条形应援毛巾\" },\n      { \"id\": \"06\", \"name\": \"帆布袋\", \"description\": \"印有蓝色 Logo 的帆布托特包\" },\n      { \"id\": \"07\", \"name\": \"亚克力钥匙扣\", \"description\": \"带有星形扣的 Q 版角色亚克力钥匙扣\" },\n      { \"id\": \"08\", \"name\": \"硅胶手环\", \"description\": \"印有 Logo 的蓝色硅胶腕带\" },\n      { \"id\": \"09\", \"name\": \"贴纸套装\", \"description\": \"4 张可见贴纸套装：Q 版角色、爱心、丝带蝴蝶结和 Logo\" },\n      { \"id\": \"10\", \"name\": \"荧光棒\", \"description\": \"蓝色发光演唱会荧光棒\" }\n    ],\n    \"footer\": {\n      \"left\": \"购买须知与指南框\",\n      \"center\": \"角色签名 'Nanashi'，带有手绘爱心和星星\",\n      \"right\": \"支付方式说明框\"\n    }\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/14209.jpg"]},{"i":7502,"text":"{\n  \"type\": \"拍立得照片合集\",\n  \"setting\": \"平铺在白色织物表面\",\n  \"character\": {\n    \"hair\": \"{argument name=\\\"hair color\\\" default=\\\"长粉色头发，内侧为蓝色\\\"}\",\n    \"outfit\": \"{argument name=\\\"outfit\\\" default=\\\"黑白女仆装，配有荷叶边发带和黑色丝带\\\"}\",\n    \"eyes\": \"红粉色\"\n  },\n  \"layout\": {\n    \"arrangement\": \"两行五张拍立得照片排列\",\n    \"count\": 10,\n    \"photos\": [\n      { \"position\": \"第一行第 1 张\", \"description\": \"抱着粉色心形靠垫\" },\n      { \"position\": \"第一行第 2 张\", \"description\": \"眨眼，比剪刀手\" },\n      { \"position\": \"第一行第 3 张\", \"description\": \"比心，底部边框有粉色心形涂鸦\" },\n      { \"position\": \"第一行第 4 张\", \"description\": \"双手托腮，温柔微笑\" },\n      { \"position\": \"第一行第 5 张\", \"description\": \"手持红玫瑰，眨眼\" },\n      { \"position\": \"第二行第 1 张\", \"description\": \"手指抵唇，害羞表情\" },\n      { \"position\": \"第二行第 2 张\", \"description\": \"拿着一个小粉色蛋糕\" },\n      { \"position\": \"第二行第 3 张\", \"description\": \"眨眼，手放在脸旁，边框上有签名 '{argument name=\\\"signature text\\\" default=\\\"Hanashi\\\"}' 和心形涂鸦\" },\n      { \"position\": \"第二行第 4 张\", \"description\": \"抱着粉色兔子玩偶，闪光涂鸦，边框上有签名 '{argument name=\\\"signature text\\\" default=\\\"Hanashi\\\"}' 和兔子涂鸦\" },\n      { \"position\": \"第二行第 5 张\", \"description\": \"眨眼，闪光涂鸦，边框上有留言 '{argument name=\\\"message text\\\" default=\\\"いつも応援ありがとう！これからもよろしくね♪\\\"}' 和签名 '{argument name=\\\"signature text\\\" default=\\\"Hanashi\\\"}'\" }\n    ]\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/14211.jpg"]},{"i":7503,"text":"{\n  \"type\": \"宣传横幅设计套装\",\n  \"theme\": \"草莓广告活动\",\n  \"style\": \"动漫插画，明亮，欢快，商业平面设计\",\n  \"color_palette\": \"{argument name=\\\"primary color theme\\\" default=\\\"柔和粉色与鲜艳红色\\\"}\",\n  \"character\": \"{argument name=\\\"character description\\\" default=\\\"扎着棕色侧马尾、戴着兔耳朵的动漫少女，身穿柔和蓝粉色外套\\\"}\",\n  \"product\": \"{argument name=\\\"product\\\" default=\\\"新鲜红草莓\\\"}\",\n  \"layout\": {\n    \"sections\": [\n      {\n        \"type\": \"大型横向横幅\",\n        \"position\": \"左上\",\n        \"visuals\": \"角色眨眼并拿着一颗草莓，旁边是一大篮草莓\",\n        \"main_text\": \"{argument name=\\\"main headline\\\" default=\\\"满满的草莓\\\"}\",\n        \"sub_text\": [\"充满笑容的甜蜜时光♪\", \"超级美味！\", \"一颗草莓，满心幸福♡\", \"好甜♡\", \"为您送上当季美味！\"],\n        \"badges\": {\n          \"count\": 3,\n          \"labels\": [\"超甜多汁！\", \"多种尺寸可选♪\", \"清晨新鲜采摘！\"]\n        }\n      },\n      {\n        \"type\": \"竖向横幅\",\n        \"position\": \"右侧\",\n        \"visuals\": \"角色正在吃草莓，下方堆放着草莓\",\n        \"main_text\": \"满满的草莓\",\n        \"sub_text\": [\"为您送上当季草莓！\", \"{argument name=\\\"secondary headline\\\" default=\\\"超甜、多汁！\\\"}\", \"融化般的美味〜♡\"],\n        \"badges\": {\n          \"count\": 3,\n          \"labels\": [\"清晨新鲜采摘！\", \"多种尺寸可选♪\", \"香甜多汁！\"]\n        }\n      },\n      {\n        \"type\": \"宽横向横幅\",\n        \"position\": \"中间\",\n        \"visuals\": \"角色闭眼吃草莓，两侧环绕着草莓\",\n        \"main_text\": \"满满的草莓！\",\n        \"sub_text\": [\"香甜多汁的幸福♡\", \"为您送上当季美味！\", \"太好吃了〜♡\"]\n      },\n      {\n        \"type\": \"小型方形横幅\",\n        \"position\": \"左下\",\n        \"visuals\": \"角色微笑着拿着草莓\",\n        \"text\": [\"满满的草莓\", \"超甜多汁！\"]\n      },\n      {\n        \"type\": \"小型方形横幅\",\n        \"position\": \"中左下\",\n        \"visuals\": \"一堆草莓，其中一颗切成两半\",\n        \"text\": [\"当季草莓！\", \"香甜融化的美味♡\"]\n      },\n      {\n        \"type\": \"小型横向横幅\",\n        \"position\": \"中右下\",\n        \"visuals\": \"角色拿着草莓\",\n        \"text\": [\"满满的草莓\", \"清晨新鲜采摘！\", \"香甜多汁！\"]\n      },\n      {\n        \"type\": \"圆形图标\",\n        \"position\": \"右下\",\n        \"count\": 4,\n        \"items\": [\n          { \"visual\": \"草莓篮\", \"label\": \"清晨新鲜采摘！\" },\n          { \"visual\": \"半颗草莓\", \"label\": \"香甜多汁！\" },\n          { \"visual\": \"整颗草莓\", \"label\": \"多种尺寸！\" },\n          { \"visual\": \"角色脸部\", \"label\": \"融化般的美味♡\" }\n        ]\n      }\n    ]\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/14212.jpg"]},{"i":7504,"text":"一张逼真的体育摄影作品，画面中恰好有 5 名长相相同的年轻亚裔男性整齐地站成一排。他们留着寸头，身穿 {argument name=\"uniform style\" default=\"带有细深色条纹的白色棒球服\"}、海军蓝内搭衫和黑色腰带。他们的胸前以海军蓝字母印有呈弧形的“{argument name=\"team name\" default=\"KANAKO\"}”字样，并带有金色勾边。他们立正站立，双手背在身后，全都微微侧向左方，表情严肃。背景为 {argument name=\"background\" default=\"模糊的绿色体育场看台\"}，展现了明亮日光下的棒球场场景。","imgs":["https://r2.qqsrc.com/images/originals/14213.jpg"]},{"i":7505,"text":"{\n  \"type\": \"水彩信息图黄历\",\n  \"style\": \"手绘风，《小王子》主题，奶油色背景，散落的星星\",\n  \"header\": {\n    \"date\": \"{argument name=\\\"date\\\" default=\\\"2026 年 4 月 18 日\\\"}\",\n    \"title\": \"{argument name=\\\"main title\\\" default=\\\"vibe coding 老黄历\\\"}\",\n    \"subtitle\": \"丙午年 三月初二 星期六\"\n  },\n  \"layout\": {\n    \"sections\": [\n      {\n        \"title\": \"宜\",\n        \"position\": \"top-left\",\n        \"count\": 5,\n        \"labels\": [\n          \"{argument name=\\\"first do item\\\" default=\\\"跟着感觉写代码\\\"}\",\n          \"和 AI 聊一聊再开工\",\n          \"删掉不对的，保留有趣的\",\n          \"给项目起一个浪漫的名字\",\n          \"喝杯咖啡，让思路长出来\"\n        ]\n      },\n      {\n        \"title\": \"今日天象 & 编程运势\",\n        \"position\": \"top-right\",\n        \"count\": 4,\n        \"labels\": [\n          \"月亮进入双子座\",\n          \"灵感流动，适合对话与创造。\",\n          \"5 stars\",\n          \"灵感 90% 调试 65% 成就感 88%\"\n        ]\n      },\n      {\n        \"title\": \"忌\",\n        \"position\": \"mid-left\",\n        \"count\": 5,\n        \"labels\": [\n          \"{argument name=\\\"first dont item\\\" default=\\\"一上来就写完美架构\\\"}\",\n          \"纠结技术选型到天黑\",\n          \"害怕报错，不敢运行\",\n          \"复制粘贴不思考\",\n          \"忘记保存与提交\"\n        ]\n      },\n      {\n        \"title\": \"今日吉时\",\n        \"position\": \"bottom-left\",\n        \"count\": 2,\n        \"labels\": [\n          \"09:30 - 11:30 灵感正旺\",\n          \"14:00 - 16:00 敲出惊喜\"\n        ]\n      },\n      {\n        \"title\": \"幸运指令\",\n        \"position\": \"bottom-left\",\n        \"count\": 4,\n        \"labels\": [\n          \"git add .\",\n          \"git commit -m \\\"follow the vibe\\\"\",\n          \"git push\",\n          \"# 宇宙会帮你编译的\"\n        ]\n      },\n      {\n        \"title\": \"今日心法\",\n        \"position\": \"bottom-right\",\n        \"count\": 1,\n        \"labels\": [\n          \"不必成为最厉害的程序员，只需成为最有感受力的创造者。让感觉引路，让代码开花。\"\n        ]\n      }\n    ],\n    \"illustration\": {\n      \"position\": \"center-right\",\n      \"subject\": \"小王子在小行星上使用笔记本电脑，旁边有狐狸、玻璃罩里的玫瑰和马克杯\",\n      \"quote\": \"{argument name=\\\"quote\\\" default=\\\"重要的东西，用眼睛是看不见的，要用代码和心去感受。\\\"} —— 小王子与程序员\",\n      \"sticky_notes\": {\n        \"count\": 3,\n        \"labels\": [\n          \"先跑起来再说。\",\n          \"让 AI 陪你探索。\",\n          \"bug 也是礼物。\"\n        ]\n      }\n    }\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/14214.jpg"]},{"i":7506,"text":"{\n  \"type\": \"4 面广告横幅变体网格\",\n  \"product\": {\n    \"name\": \"{argument name=\\\"product name\\\" default=\\\"HP BOOSTER\\\"}\",\n    \"subtitle\": \"AI 驱动的无代码网站构建器\",\n    \"logo\": \"带有菱形的蓝色和绿色尖括号\"\n  },\n  \"common_elements\": {\n    \"device_mockups\": \"笔记本电脑和智能手机（左下角面板为桌面显示器），展示了一个带有城市天际线、文字“未来，尽在你的业务中。”以及蓝色“立即开始”按钮的网站\"\n  },\n  \"layout\": {\n    \"grid\": \"2x2\",\n    \"panels\": [\n      {\n        \"position\": \"左上\",\n        \"theme\": \"深蓝色渐变配科技线条\",\n        \"headline\": \"{argument name=\\\"main headline 1\\\" default=\\\"最快 10 分钟，打造专业级网站。\\\"}\",\n        \"sub_headline\": \"AI 自动生成设计、架构和文案\",\n        \"badge\": \"金色月桂花环，文字“引入企业持续增加中！”\",\n        \"icon_count\": 5,\n        \"icon_labels\": [\"AI 自动创建与优化\", \"无代码自由编辑\", \"设计自由且专业\", \"SEO 优化一站式搞定\", \"移动端适配与高速加载\"],\n        \"bottom_bar\": \"青色背景，黄色按钮“立即免费开始 ▶”\"\n      },\n      {\n        \"position\": \"右上\",\n        \"theme\": \"白色和浅灰色\",\n        \"headline\": \"{argument name=\\\"main headline 2\\\" default=\\\"AI 助力，人人皆可轻松上手。\\\"}\",\n        \"pre_headline\": \"让网站制作常识变得更简单。\",\n        \"badge\": \"青色圆圈，文字“无需专业知识与制作技能！”\",\n        \"icon_count\": 4,\n        \"icon_labels\": [\"AI 自动创建与优化\", \"无代码自由编辑\", \"移动端适配与高速加载\", \"SEO 优化一站式搞定\"],\n        \"bottom_bar\": \"青色背景，黄色按钮“免费开始 ▶”\"\n      },\n      {\n        \"position\": \"左下\",\n        \"theme\": \"亮黄色配漫画风格动作线条\",\n        \"headline\": \"{argument name=\\\"main headline 3\\\" default=\\\"自己动手！最快 10 分钟完成网站制作！\\\"}\",\n        \"pre_headline\": \"无需再依赖制作公司！\",\n        \"badge\": \"粉色圆圈，文字“AI 全自动生成！”\",\n        \"icon_count\": 6,\n        \"icon_labels\": [\"AI 自动生成\", \"无代码\", \"设计自由\", \"SEO 优化\", \"移动端适配\", \"高速加载\"],\n        \"call_to_action\": \"粉色胶囊按钮“免费开始！▶”\"\n      },\n      {\n        \"position\": \"右下\",\n        \"theme\": \"深灰色和黑色\",\n        \"headline\": \"{argument name=\\\"main headline 4\\\" default=\\\"打造能带来成果的网站。\\\"}\",\n        \"pre_headline\": \"若想认真提升获客能力，\",\n        \"badge\": \"金色月桂花环，文字“引入企业持续增加中！”\",\n        \"icon_count\": 4,\n        \"icon_labels\": [\"AI 从架构到文案自动生成\", \"无代码自由定制\", \"SEO、速度与安全性保障\", \"全面支持获客与业绩提升\"],\n        \"bottom_bar\": \"金色背景，深蓝色按钮“立即免费开始 ▶”\"\n      }\n    ]\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/14215.jpg"]},{"i":7507,"text":"{\n  \"type\": \"电影级插画与综合概念艺术参考图集\",\n  \"overall_theme\": \"科幻深海探索\",\n  \"layout\": {\n    \"top_half\": \"电影级关键视觉图\",\n    \"bottom_half\": \"高密度多面板参考图集\"\n  },\n  \"top_half_details\": {\n    \"typography\": {\n      \"main_title\": \"{argument name=\\\"main title\\\" default=\\\"深渊地平线 ABYSS HORIZON\\\"}\",\n      \"taglines\": [\"人类开启了深海之门。那里是一个超越想象的世界。\", \"黑暗并非终点。而是人类的新起点。\"]\n    },\n    \"scene\": \"两名角色站在阳台上，俯瞰宏大的深海环境。\",\n    \"characters\": [\n      {\n        \"description\": \"男性，深色头发，背对镜头，身穿深蓝色夹克\",\n        \"jacket_text\": \"NEREIS-01 研究团队负责人 {argument name=\\\"male character name\\\" default=\\\"FUKAMI YOU\\\"}\"\n      },\n      {\n        \"description\": \"女性，棕色头发盘起，侧面视角，身穿深蓝色夹克\",\n        \"jacket_text\": \"I.D.T.O. 观察员 {argument name=\\\"female character name\\\" default=\\\"A. VOLKOV\\\"}\"\n      }\n    ],\n    \"background_elements\": [\n      {\n        \"type\": \"巨型潜水艇\",\n        \"label\": \"{argument name=\\\"submarine name\\\" default=\\\"NEREIS-01\\\"}\"\n      },\n      {\n        \"type\": \"巨大的发光生物机械结构\",\n        \"label\": \"{argument name=\\\"base structure name\\\" default=\\\"ABYSS ANCHOR\\\"} -13,000 米\"\n      }\n    ]\n  },\n  \"bottom_half_details\": {\n    \"sections\": [\n      {\n        \"title\": \"世界观设定图\",\n        \"content\": \"比例对比图，展示 2 名角色、2 艘潜水艇和 1 只生物。\"\n      },\n      {\n        \"title\": \"ANA VOLKOV\",\n        \"content\": \"女性角色参考。包含 3 个全身转向图（正面、背面、侧面）、4 种面部表情以及 3 张靴子和配饰的细节特写。\"\n      },\n      {\n        \"title\": \"FUKAMI YOU\",\n        \"content\": \"男性角色参考。包含 3 个全身转向图（正面、背面、侧面）、4 种面部表情以及 3 张手套和腕部设备的细节特写。\"\n      },\n      {\n        \"title\": \"VOID CROWN\",\n        \"content\": \"生物设计图。包含 4 个带刺、触手状深海生物的详细视图。\"\n      },\n      {\n        \"title\": \"超深海前线调查基地 ABYSS ANCHOR\",\n        \"content\": \"结构示意图。包含 3 个深海基地的详细建筑视图。\"\n      },\n      {\n        \"title\": \"深海探査艇 NEREIS\",\n        \"content\": \"潜水艇示意图。包含 4 个主载具的详细正投影和透视视图。\"\n      }\n    ]\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/14216.jpg"]},{"i":7508,"text":"一张虚构日常系动漫的动漫风格主视觉海报。左前方，一位充满活力的金发动漫少女戴着星星发夹，有着蓝色双眼，身穿 {argument name=\"main character outfit\" default=\"美国国旗 T 恤和牛仔短裤\"}，正拿着烤肉夹向观众递出一片烟熏肉。右前方，一位留着长黑发、身穿白色毛衣的温柔女孩坐在木桌旁写着笔记。背景中还有另外两名女孩：一位扎着棕色马尾辫，正搬运着木柴；另一位留着银色短发，手里拿着一个蓝色马克杯。场景设定在阳光明媚的户外烧烤区，设有一个大型黑色烟熏烤炉，上面挂着写有 {argument name=\"background grill sign\" default=\"LONE STAR BBQ\"} 的招牌。最前方是一个 {argument name=\"food platter\" default=\"盛满切片牛胸肉、排骨、香肠、焦边肉和酸黄瓜的大型木制拼盘\"}，旁边还有凉拌卷心菜和面包等配菜。左上角是一个大型、可爱且充满活力的动漫 Logo，写着 {argument name=\"anime title\" default=\"もくもく すもーく ガールズ\"}，并配有烟雾和烧烤图案。左下角有一个 {argument name=\"credits text block\" default=\"包含姓名和职位的制作人员名单块\"}。右下角的小文本框列出了四个角色的名字。整体氛围欢快、细节丰富且充满活力。","imgs":["https://r2.qqsrc.com/images/originals/14217.jpg"]},{"i":7509,"text":"一个可爱的 kawaii 风格 {argument name=\"subject\" default=\"云朵\"} 角色的 3D 渲染图，背景为纯白色。该角色具有柔软、哑光且富有弹性的质感，类似于粘土或解压玩具。它拥有明亮的大黑眼睛，带有白色高光、简单的弧形微笑以及圆润的粉色腮红。角色的边缘和底部带有 {argument name=\"accent colors\" default=\"粉色、蓝色和紫色\"} 的柔和渐变色。柔和的摄影棚灯光，极简图标风格，投射出淡淡的阴影。","imgs":["https://r2.qqsrc.com/images/originals/14218.jpg"]},{"i":7510,"text":"{\n  \"type\": \"促销横幅广告\",\n  \"theme\": \"母亲节鲜花礼品\",\n  \"visual_style\": \"柔和、优雅、女性化、柔和色调，背景散落着粉色花瓣\",\n  \"imagery\": {\n    \"bouquet\": \"一大束 {argument name=\\\"color theme\\\" default=\\\"粉色\\\"} 康乃馨和玫瑰，用粉色包装纸包裹并系有丝带，放置在右侧\",\n    \"tag\": \"挂在花束上的白色长方形标签，上面写着 '{argument name=\\\"tag text\\\" default=\\\"谢谢妈妈！\\\"}' 并绘有爱心\"\n  },\n  \"layout\": {\n    \"main_typography\": {\n      \"position\": \"左上至左中\",\n      \"top_arch\": \"致最爱的妈妈，\",\n      \"sub_arch\": \"\\\\ 将感恩之情寄托于花朵。 /\",\n      \"headline_1\": \"在 {argument name=\\\"main event\\\" default=\\\"母亲节\\\"}\",\n      \"headline_2\": \"送上一份 {argument name=\\\"product name\\\" default=\\\"鲜花礼品\\\"}\",\n      \"headline_3\": \"表达心意\"\n    },\n    \"details_section\": {\n      \"position\": \"页脚上方的左下角\",\n      \"badge\": \"圆形徽章，文字为 '{argument name=\\\"event date\\\" default=\\\"5.12\\\"} 周日 母亲节'\",\n      \"description_text\": \"将感谢的心意融入花朵， 让特别的一天更加绚丽多彩。\"\n    },\n    \"footer\": {\n      \"position\": \"底部边缘\",\n      \"style\": \"白色横条\",\n      \"count\": 3,\n      \"items\": [\n        { \"icon\": \"delivery truck\", \"text\": \"支持全国配送\", \"subtext\": \"※部分地区除外\" },\n        { \"icon\": \"gift box\", \"text\": \"免费礼品包装\" },\n        { \"icon\": \"calendar\", \"text\": \"5 月 10 日（周五）前下单，母亲节当天送达\" }\n      ]\n    }\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/14219.jpg"]},{"i":7511,"text":"{\n  \"type\": \"2 页漫画跨页\",\n  \"style\": \"黑白动漫漫画，网点纸效果\",\n  \"theme\": \"{argument name=\\\"main action\\\" default=\\\"奇幻法师正在开发一款电子游戏\\\"}\",\n  \"character\": \"{argument name=\\\"character appearance\\\" default=\\\"金发动漫少女，戴着头冠，披着斗篷，身穿白色连衣裙，穿着过膝袜\\\"}\",\n  \"layout\": {\n    \"left_page\": {\n      \"panel_count\": 11,\n      \"rows\": [\n        {\"panels\": 1, \"action\": \"在双显示器桌前神情坚定，对话气泡：'新作ゲーム、絶対完成させる！'\"},\n        {\"panels\": 3, \"action\": \"打字、在数位板上绘图、用手柄测试\"},\n        {\"panels\": 3, \"action\": \"对错误屏幕感到震惊，沮丧，再次坚定\"},\n        {\"panels\": 4, \"action\": \"筋疲力尽，突然顿悟，疯狂打字，显示器显示 'Build succeeded!'\"}\n      ]\n    },\n    \"right_page\": {\n      \"panel_count\": 2,\n      \"panels\": [\n        {\"type\": \"大跨页\", \"action\": \"从发光的圆环中施展魔法，攻击标有 '{argument name=\\\"error text\\\" default=\\\"NullReferenceException\\\"}' 的代码错误怪物。对话气泡：'{argument name=\\\"spell text\\\" default=\\\"デバッグ魔法!!\\\"}'\"},\n        {\"type\": \"底部横幅\", \"action\": \"在 RPG 标题画面前欢呼。对话气泡：'{argument name=\\\"success text\\\" default=\\\"やったー！\\\"}'\"}\n      ]\n    }\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/14220.jpg"]},{"i":7512,"text":"{\n  \"type\": \"4 格讽刺产品广告网格\",\n  \"layout\": {\n    \"grid\": \"2x2\",\n    \"panels\": [\n      {\n        \"position\": \"左上\",\n        \"product_name\": \"{argument name=\\\"top left product name\\\" default=\\\"座る石\\\"}\",\n        \"visual\": \"一名身穿白衬衫、深色长裤的男子坐在公园的一块大圆石上\",\n        \"catchphrase\": \"随时随地，安稳休憩。\",\n        \"sales_badge\": \"累计销量突破 12,000 个！\",\n        \"vertical_text\": \"当公园长椅都被占满时。\",\n        \"features_count\": 3,\n        \"features_labels\": [\n          \"重约 8kg，稳定性极佳\",\n          \"底部毛毡处理，不易刮伤地面\",\n          \"附带专用背带，携带方便\"\n        ],\n        \"extra_visual\": \"带有皮革背带的石头小图\",\n        \"specs\": [\n          \"承重 150kg\",\n          \"安心的日本制造\"\n        ]\n      },\n      {\n        \"position\": \"右上\",\n        \"product_name\": \"{argument name=\\\"top right product name\\\" default=\\\"磨きたくない人の歯ブラシ\\\"}\",\n        \"visual\": \"一支时尚的浅蓝色牙刷斜放在深蓝色背景上\",\n        \"toothbrush_text\": \"I don't want to brush my teeth.\",\n        \"catchphrase\": \"拿在手里，心安理得\",\n        \"vertical_text\": \"与其刷牙，不如拿着它。\",\n        \"sales_badge\": \"系列累计销量突破 85,000 支！\",\n        \"features_count\": 3,\n        \"features_labels\": [\n          \"作为平复心情的护身符\",\n          \"会议或商务洽谈前的礼仪\",\n          \"让“不刷牙”的选择更自由。\"\n        ],\n        \"bottom_banner\": \"将你从刷牙的压力中解放出来。\"\n      },\n      {\n        \"position\": \"左下\",\n        \"product_name\": \"{argument name=\\\"bottom left product name\\\" default=\\\"雲の貯金箱\\\"}\",\n        \"visual\": \"一只手正将硬币投入云朵形状的毛绒储蓄罐中\",\n        \"catchphrase\": \"比空气更轻的安心感。\",\n        \"sales_badge\": \"累计销量突破 23,567 个！\",\n        \"features_count\": 3,\n        \"features_labels\": [\n          \"蓬松柔软的触感\",\n          \"摔不坏，更安心\",\n          \"融入家居装饰的设计\"\n        ],\n        \"color_variants_count\": 3,\n        \"color_variants_labels\": [\n          \"蓝色\",\n          \"粉色\",\n          \"白色\"\n        ],\n        \"price\": \"¥2,980 (含税)\",\n        \"bottom_text\": \"从今天起，向着天空一点点积攒吧。\"\n      },\n      {\n        \"position\": \"右下\",\n        \"product_name\": \"{argument name=\\\"bottom right product name\\\" default=\\\"叱ってくれる石\\\"}\",\n        \"visual\": \"书桌上的一块圆石，旁边放着一支笔，石头上写着字\",\n        \"stone_text\": \"{argument name=\\\"scolding phrase\\\" default=\\\"いいかげんやれ\\\"}\",\n        \"catchphrase\": \"献给提不起干劲的你。\",\n        \"sales_badge\": \"累计销量突破 18,000 个！\",\n        \"features_count\": 3,\n        \"features_labels\": [\n          \"每次看到都能振奋人心\",\n          \"随机显示精选的鞭策语录\",\n          \"无需电池，半永久性地督促你\"\n        ],\n        \"phrase_variants_count\": 10,\n        \"phrase_variants_labels\": [\n          \"别撒娇了\",\n          \"别多想\",\n          \"行动起来\",\n          \"认清现实吧\",\n          \"别逃避\",\n          \"别睡觉\",\n          \"只要做就能行\",\n          \"如果是你一定可以\",\n          \"别睡觉\",\n          \"别再找借口了\"\n        ],\n        \"price\": \"¥3,500 (含税)\"\n      }\n    ]\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/14221.jpg"]},{"i":7513,"text":"一张电影质感的科幻动画电影海报，画面中是一艘重装甲圆柱形深海潜水艇，停靠在岩石嶙峋的海底。潜水艇拥有一个发着青色光芒的中央舷窗、一圈小型灯光、两个明亮的向下探照灯，侧面印有“{argument name=\"hull text\" default=\"NEREIS-01\"}”字样。在它身后，隐约浮现出一个 {argument name=\"creature type\" default=\"巨大的生物发光海葵状实体\"}，其触手末端放射着青色的光芒。深青色的深渊中点缀着发光的海底植物。左上角的文字包括日文标题“{argument name=\"main title\" default=\"深淵の地平線\"}”、副标题“{argument name=\"english subtitle\" default=\"ABYSS HORIZON\"}”以及标语“{argument name=\"tagline\" default=\"暗黒は、終わりじゃない。人類の新しい始まりだ。\"}”。底部的技术性脚注文字左侧为“INTERNATIONAL DEEP SEA TREATY ORGANIZATION”，右侧为“IDTO-AB-013300-ALPHA”。细节丰富，光影效果极具戏剧性，工业机甲设计。","imgs":["https://r2.qqsrc.com/images/originals/14222.jpg"]},{"i":7514,"text":"一张动漫风格的宣传插画，描绘了 3 位角色在明亮的蓝天白云下，于欢乐的绘画场景中动态奔跑的画面。左侧是一位身穿优雅白色荷叶边连衣裙、戴着手套的金发年轻女性，她笑容灿烂，手中拿着一支滴着粉色颜料的画笔。中间是一位身穿蓝色背带裤和黑色 T 恤的黑发年轻男子，他神情兴奋，手中拿着一卷美纹纸胶带和一个绿色滚筒刷。右侧是一位开怀大笑的年长男子，身穿深色日式传统工作服，脖子上围着一条白毛巾。五彩斑斓的颜料飞溅在空中，周围漂浮着 2 个油漆桶、2 把画笔和 2 卷美纹纸胶带等道具。顶部是一个风格化的标题 Logo，显示为 {argument name=\"main title\" default=\"お嬢様は塗装を知らない\"}，并装饰有颜料飞溅效果。下方是一条横幅丝带，写着 {argument name=\"subtitle\" default=\"清楚なお嬢様 × 塗装男子\"}。底部是一句醒目的宣传标语：{argument name=\"bottom tagline\" default=\"未知の世界でふたりの距離が縮まっていく…！\"}。整体风格呈现出鲜艳的色彩和轻小说封面的美感。","imgs":["https://r2.qqsrc.com/images/originals/14223.jpg"]},{"i":7515,"text":"{\n  \"type\": \"网页广告横幅\",\n  \"style\": \"简洁、现代、明亮，带有柔和的渐变色点缀，角落有圆点图案\",\n  \"background_image\": \"{argument name=\\\"subject description\\\" default=\\\"年轻的日本女性微笑着，看着笔记本电脑屏幕，手托着下巴，穿着白色衬衫\\\"}，明亮的自然光，桌上放着白色马克杯\",\n  \"typography\": {\n    \"catchphrase\": {\n      \"text\": \"{argument name=\\\"catchphrase\\\" default=\\\"将热爱转化为职业的能力\\\"}\",\n      \"style\": \"手写字体，蓝色和紫色下划线\"\n    },\n    \"headline\": {\n      \"text\": \"{argument name=\\\"main headline\\\" default=\\\"用 Web 设计改变未来。\\\"}\",\n      \"style\": \"大号粗体无衬线字体，黑色与蓝紫渐变色\"\n    },\n    \"subheadline\": {\n      \"text\": \"从零基础到专业 Web 设计师。\",\n      \"style\": \"中号无衬线字体，黑色搭配蓝色高亮\"\n    }\n  },\n  \"layout\": {\n    \"feature_icons\": {\n      \"count\": 3,\n      \"style\": \"带有极简图标的圆形白色徽章，下方附有文字标签\",\n      \"items\": [\n        { \"icon\": \"打开的书\", \"label\": \"零基础友好\" },\n        { \"icon\": \"笔记本电脑\", \"label\": \"100% 在线学习\" },\n        { \"icon\": \"带对话气泡的人\", \"label\": \"活跃设计师提供支持\" }\n      ]\n    },\n    \"bottom_section\": {\n      \"satisfaction_badge\": {\n        \"text_top\": \"学员满意度\",\n        \"value\": \"{argument name=\\\"satisfaction rate\\\" default=\\\"94%\\\"}\",\n        \"text_bottom\": \"*内部调研\",\n        \"decoration\": \"金色月桂花环\"\n      },\n      \"cta_button\": {\n        \"style\": \"药丸形，蓝粉渐变背景，白色文字，带向右箭头图标\",\n        \"microcopy\": \"\\\\ 先免费咨询 /\",\n        \"main_text\": \"{argument name=\\\"call to action text\\\" default=\\\"申请免费咨询\\\"}\"\n      }\n    }\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/14224.jpg"]},{"i":7516,"text":"一个奢华的化妆品产品广告，画面中央是一个优雅的玻璃罐，配有闪亮的金色瓶盖，放置在圆形的浅色大理石板上。罐身上印有金色文字 {argument name=\"brand name\" default=\"LUMIÉRE\"} 和 {argument name=\"product type\" default=\"MOISTURE RICH CREAM\"}，下方标注有 \"AGING CARE*\"。背景由柔软、垂坠且闪烁着香槟色光泽的丝绸织物构成，左侧点缀着精致的白色花朵。光线温暖、空灵，如同沐浴在阳光下，并带有柔和的焦外成像效果。在顶部中央，优雅的深棕色日文排版显示为 {argument name=\"main headline\" default=\"肌に、静かな贅沢を。\"}，下方是一个小巧的金色装饰分隔线，以及文字 {argument name=\"subheadline\" default=\"高保湿×エイジングケア*\"}。在罐子右侧，一个细金圆圈内包含日文，意为“以浓郁滋润，赋予高品质的紧致与光泽”。底部中央是一个深色矩形行动号召按钮，带有细金色边框，内含文字 {argument name=\"button text\" default=\"詳しく見る\"} 和一个向右的箭头符号。右下角有极小的细则文字，意为“*指根据年龄进行的护理”。","imgs":["https://r2.qqsrc.com/images/originals/14225.jpg"]},{"i":7517,"text":"{\n  \"type\": \"VTuber 直播缩略图\",\n  \"character\": {\n    \"hair\": \"长款金色双马尾，发梢带有粉色渐变\",\n    \"eyes\": \"大大的粉色动漫眼睛\",\n    \"expression\": \"开心的笑容，露出小虎牙，在眼睛附近比出剪刀手\",\n    \"outfit\": \"黑色上衣搭配背带，黑色心形环颈圈，多处耳饰（包括十字架吊坠），黑色指甲油\"\n  },\n  \"background\": \"充满活力的霓虹粉色与黑色豹纹背景，带有发光的黄色装饰、闪光点和漂浮的心形\",\n  \"typography_and_layout\": {\n    \"main_title\": {\n      \"position\": \"左上角\",\n      \"style\": \"大号、粗体、3D 效果，粉黑配色，带有白色描边\",\n      \"text\": \"{argument name=\\\"main title\\\" default=\\\"雑談配信\\\"}\"\n    },\n    \"top_right_text\": {\n      \"style\": \"带有心形装饰的随性手写风格\",\n      \"text\": \"{argument name=\\\"top right text\\\" default=\\\"まったり話そ〜♡\\\"}\"\n    },\n    \"bottom_left_banners\": {\n      \"count\": 3,\n      \"style\": \"发光的药丸状横幅，左侧带有心形图标\",\n      \"colors\": [\"粉色\", \"黄色\", \"紫色\"],\n      \"labels\": [\n        \"{argument name=\\\"banner 1 text\\\" default=\\\"初見さん〇\\\"}\",\n        \"{argument name=\\\"banner 2 text\\\" default=\\\"ポイント回収〇\\\"}\",\n        \"{argument name=\\\"banner 3 text\\\" default=\\\"ROM〇\\\"}\"\n      ]\n    },\n    \"bottom_right_text\": {\n      \"style\": \"带有心形装饰的随性手写风格，黄色文字配粉色描边\",\n      \"text\": \"気軽にコメントしてねっ♡\"\n    }\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/14227.jpg"]},{"i":7518,"text":"{\n  \"type\": \"商业活动广告横幅\",\n  \"background\": \"带有发光节点和现代城市剪影的抽象蓝色数字网格\",\n  \"layout\": {\n    \"header\": {\n      \"catchphrase_top\": \"学习最新趋势，迈向未来一步！\",\n      \"main_title\": \"{argument name=\\\"main title\\\" default=\\\"商业未来战略峰会\\\"}\",\n      \"badge\": {\n        \"shape\": \"黄色圆形\",\n        \"text\": \"免费参加\",\n        \"position\": \"右上角\"\n      },\n      \"date_and_location\": \"{argument name=\\\"event date\\\" default=\\\"2026 年 5 月 16 日（周六）・17 日（周日）在线举办\\\"}\",\n      \"sub_catchphrases\": [\n        \"在家或办公室即可轻松参加！\",\n        \"顶尖讲师的特别演讲！\"\n      ]\n    },\n    \"centerpiece\": {\n      \"description\": \"身着商务休闲装和正式企业服装的日本职场人士集体照\",\n      \"count\": 9\n    },\n    \"topic_banners\": {\n      \"count\": 3,\n      \"style\": \"水平矩形丝带\",\n      \"labels\": [\n        \"{argument name=\\\"topic 1\\\" default=\\\"DX-AI 的最新应用方法\\\"}\",\n        \"{argument name=\\\"topic 2\\\" default=\\\"新时代的营销策略\\\"}\",\n        \"{argument name=\\\"topic 3\\\" default=\\\"业务增长的成功案例\\\"}\"\n      ]\n    },\n    \"footer\": {\n      \"call_to_action\": {\n        \"text_lines\": [\n          \"立即预注册！\",\n          \"点击此处注册观看\"\n        ],\n        \"icon\": \"向右箭头\"\n      },\n      \"devices\": {\n        \"count\": 2,\n        \"items\": [\n          \"显示 'ONLINE SUMMIT' 的笔记本电脑\",\n          \"显示 'ONLINE SUMMIT' 的智能手机\"\n        ]\n      },\n      \"qr_code\": {\n        \"count\": 1,\n        \"label\": \"QR 码\"\n      },\n      \"bottom_bar\": \"详情请查看网站！\"\n    }\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/14228.jpg"]},{"i":7519,"text":"{\n  \"type\": \"旅行广告网页横幅\",\n  \"layout\": {\n    \"background\": \"{argument name=\\\"scenery type\\\" default=\\\"雄伟的雪山和绿松石色的湖泊\\\"}，松树，蜿蜒的柏油路，万里无云的湛蓝天空\",\n    \"foreground_right\": \"{argument name=\\\"car color\\\" default=\\\"浅蓝色\\\"} SUV 行驶在路上，后备箱打开装有行李，车顶行李架已装载，木制路标写着 'NEXT ADVENTURE'\",\n    \"typography_left\": {\n      \"top_ribbon\": \"金色丝带，带有文字 'まだ見ぬ絶景へ。' 和小鸟图案\",\n      \"main_headline\": \"大型衬线字体 '{argument name=\\\"main headline\\\" default=\\\"回归自然，深呼吸。\\\"}'，采用深蓝色渐变\",\n      \"sub_headline\": \"文字 '{argument name=\\\"sub headline\\\" default=\\\"出发吧，让心灵放晴。\\\"}'，配有细线条和山脉图形\"\n    },\n    \"ui_elements\": {\n      \"cta_button\": \"药丸状蓝绿渐变按钮，文字为 '{argument name=\\\"cta button text\\\" default=\\\"查看推荐 >\\\"}'\",\n      \"bottom_bar\": {\n        \"description\": \"白色页脚栏\",\n        \"count\": 3,\n        \"items\": [\n          {\"icon\": \"山脉与道路\", \"text\": \"绝景自驾\"},\n          {\"icon\": \"相机与树叶\", \"text\": \"焕新之旅\"},\n          {\"icon\": \"日历与树木\", \"text\": \"周末畅游\"}\n        ]\n      }\n    }\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/14229.jpg"]}];